1	"use client";
2	
3	import { useState, useTransition } from "react";
4	import { scanSource, planConsolidationMigration, startConsolidationMigration, type ScanResult } from "@/lib/actions-migrate";
5	
6	type ServerOpt = { id: string; name: string };
7	type Row = { host: string; port: string; user: string; password: string; scan?: ScanResult | null; scanError?: string };
8	type Plan = Awaited<ReturnType<typeof planConsolidationMigration>>["plan"];
9	
10	const blank = (): Row => ({ host: "", port: "22", user: "root", password: "" });
11	
12	export function ConsolidateWizard({ servers }: { servers: ServerOpt[] }) {
13	  const [target, setTarget] = useState(servers[0]?.id ?? "");
14	  const [rows, setRows] = useState<Row[]>([blank(), blank()]);
15	  const [plan, setPlan] = useState<Plan | undefined>();
16	  const [blocked, setBlocked] = useState<string | null>(null);
17	  const [msg, setMsg] = useState<string | null>(null);
18	  const [done, setDone] = useState<string[] | null>(null);
19	  // Per-migration SAFETY opt-ins, applied to every source in this consolidation.
20	  // All default OFF; passed to startConsolidationMigration as each source's
21	  // `options` (the worker keeps every safety default unless ticked).
22	  const [overwriteTargetData, setOverwriteTargetData] = useState(false);
23	  const [renameClones, setRenameClones] = useState(false);
24	  const [copySshKeys, setCopySshKeys] = useState(false);
25	  const [pending, start] = useTransition();
26	
27	  const setRow = (i: number, patch: Partial<Row>) => setRows((r) => r.map((x, j) => (j === i ? { ...x, ...patch } : x)));
28	  const addRow = () => rows.length < 5 && setRows((r) => [...r, blank()]);
29	  const delRow = (i: number) => rows.length > 2 && setRows((r) => r.filter((_, j) => j !== i));
30	
31	  const review = () =>
32	    start(async () => {
33	      setMsg(null); setBlocked(null); setPlan(undefined); setDone(null);
34	      if (!target) return setMsg("Pick a target server.");
35	      const sources: { label: string; host: string; scan: ScanResult; domains?: string[] }[] = [];
36	      const next = [...rows];
37	      for (let i = 0; i < next.length; i++) {
38	        const r = next[i];
39	        if (!r.host || !r.password) { setMsg("Every source needs a host and SSH password."); return; }
40	        const res = await scanSource({ serverId: target, sourceHost: r.host, sourcePort: Number(r.port) || 22, sourceUser: r.user || "root", sourcePassword: r.password });
41	        if (res.error || !res.scan) { next[i] = { ...r, scanError: res.error ?? "Scan failed" }; setRows([...next]); setMsg(`Couldn't scan ${r.host}: ${res.error ?? "unknown error"}`); return; }
42	        next[i] = { ...r, scan: res.scan, scanError: undefined };
43	        sources.push({ label: r.host, host: r.host, scan: res.scan });
44	      }
45	      setRows(next);
46	      const res = await planConsolidationMigration({ serverId: target, sources });
47	      if (res.error) return setMsg(res.error);
48	      setPlan(res.plan);
49	    });
50	
51	  const run = () =>
52	    start(async () => {
53	      setMsg(null); setBlocked(null);
54	      const options = { overwriteTargetData, renameClones, copySshKeys };
55	      const sources = rows.filter((r) => r.scan).map((r) => ({ sourceHost: r.host, sourcePort: Number(r.port) || 22, sourceUser: r.user || "root", sourcePassword: r.password, scan: r.scan!, options }));
56	      const res = await startConsolidationMigration({ serverId: target, sources });
57	      if (res.blockers?.length) { setBlocked(res.error ?? "Overlaps must be resolved first."); setPlan(res.plan); return; }
58	      if (res.error) return setMsg(res.error);
59	      setDone(res.ids ?? []);
60	    });
61	
62	  const hasBlockers = (plan?.collisions ?? []).some((c) => c.kind === "port" || c.kind === "path");
63	
64	  return (
65	    <div className="card">
66	      <h2 className="text-lg font-semibold text-white">Consolidate servers onto one box</h2>
67	      <p className="mt-1 text-sm text-slate-400">Move several source servers onto a single Nxeon server. We scan each one, flag anything that would collide, and run the migrations one after another.</p>
68	
69	      <label className="label mt-5">Target Nxeon server</label>
70	      <select value={target} onChange={(e) => setTarget(e.target.value)} className="input">
71	        {servers.length === 0 && <option value="">No servers yet</option>}
72	        {servers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
73	      </select>
74	
75	      <div className="mt-6 space-y-3">
76	        {rows.map((r, i) => (
77	          <div key={i} className="rounded-xl border border-white/10 bg-white/[0.02] p-4">
78	            <div className="mb-2 flex items-center justify-between">
79	              <span className="text-sm font-medium text-slate-300">Source {i + 1}{r.scan ? " · scanned ✓" : ""}</span>
80	              {rows.length > 2 && <button onClick={() => delRow(i)} className="text-xs text-slate-500 hover:text-red-300">remove</button>}
81	            </div>
82	            <div className="grid gap-2 sm:grid-cols-[1fr_5rem_6rem_1fr]">
83	              <input className="input" placeholder="host or IP" value={r.host} onChange={(e) => setRow(i, { host: e.target.value, scan: null })} />
84	              <input className="input" placeholder="port" value={r.port} onChange={(e) => setRow(i, { port: e.target.value })} />
85	              <input className="input" placeholder="ssh user" value={r.user} onChange={(e) => setRow(i, { user: e.target.value })} />
86	              <input className="input" type="password" placeholder="ssh password" value={r.password} onChange={(e) => setRow(i, { password: e.target.value })} />
87	            </div>
88	            {r.scanError && <p className="mt-2 text-xs text-red-300">{r.scanError}</p>}
89	          </div>
90	        ))}
91	      </div>
92	      <div className="mt-3 flex items-center gap-3">
93	        {rows.length < 5 && <button onClick={addRow} className="btn-secondary text-sm">+ Add source</button>}
94	        <button onClick={review} disabled={pending} className="btn-secondary text-sm">{pending ? "Scanning…" : "Scan & review plan"}</button>
95	      </div>
96	
97	      {/* Advanced options — per-migration SAFETY opt-ins, applied to every source. All OFF by default. */}
98	      <details className="mt-4 rounded-xl border border-white/10 bg-white/[0.02] p-3">
99	        <summary className="cursor-pointer text-xs font-medium text-slate-300">Advanced options</summary>
100	        <div className="mt-3 space-y-2">
101	          {[
102	            {
103	              checked: overwriteTargetData,
104	              onToggle: () => setOverwriteTargetData((v) => !v),
105	              title: "Replace existing data on the destination",
106	              sub: "If the target already has a database or files with the same name, overwrite them. Off by default — we refuse and tell you instead.",
107	            },
108	            {
109	              checked: renameClones,
110	              onToggle: () => setRenameClones((v) => !v),
111	              title: "Bring up staging clones by renaming containers",
112	              sub: "If two of your compose stacks share the same container name (e.g. prod + staging), rename the clone's containers so both can run. Off by default.",
113	            },
114	            {
115	              checked: copySshKeys,
116	              onToggle: () => setCopySshKeys((v) => !v),
117	              title: "Copy SSH authorized_keys",
118	              sub: "Bring your deploy/ops SSH keys across (public keys only — never private keys). Off by default.",
119	            },
120	          ].map((opt) => (
121	            <label
122	              key={opt.title}
123	              className={`flex cursor-pointer items-start gap-3 rounded-lg border p-3 transition ${
124	                opt.checked ? "border-brand-400/50 bg-brand-500/[0.07]" : "border-white/10 bg-white/[0.03] hover:border-white/20"
125	              }`}
126	            >
127	              <input type="checkbox" checked={opt.checked} onChange={opt.onToggle} className="mt-0.5 h-4 w-4 shrink-0 cursor-pointer accent-brand-500" />
128	              <span className="text-xs">
129	                <span className="font-medium text-slate-100">{opt.title}</span>
130	                <span className="mt-1 block text-slate-400">{opt.sub}</span>
131	              </span>
132	            </label>
133	          ))}
134	        </div>
135	      </details>
136	
137	      {msg && <p className="mt-4 rounded-lg border border-amber-400/25 bg-amber-400/[0.06] px-3 py-2 text-sm text-amber-200">{msg}</p>}
138	
139	      {plan && (
140	        <div className="mt-6 rounded-xl border border-white/10 bg-navy-950/40 p-4">
141	          <p className="section-label">Consolidation plan</p>
142	          {plan.collisions.length === 0 ? (
143	            <p className="mt-2 text-sm text-emerald-300">✓ No collisions — these servers merge cleanly. Nothing needs remapping.</p>
144	          ) : (
145	            <ul className="mt-3 space-y-1.5 text-sm">
146	              {plan.collisions.map((c, i) => {
147	                const block = c.kind === "port" || c.kind === "path";
148	                return (
149	                  <li key={i} className={`flex flex-wrap items-center gap-2 ${block ? "text-red-300" : "text-amber-200"}`}>
150	                    <span className="rounded bg-white/10 px-1.5 py-0.5 font-mono text-[11px] uppercase">{c.kind}</span>
151	                    <span className="font-mono">{c.value}</span>
152	                    {c.kind === "port" && c.appName && c.appName.split(":")[0] !== "svc" && (
153	                      <span className="font-mono text-slate-400">({c.appName.split(":")[0]})</span>
154	                    )}
155	                    <span className="text-slate-500">({c.sourceLabel} vs {c.heldBy})</span>
156	                    <span className="text-slate-400">→ {c.remappedTo}</span>
157	                    {block && <span className="text-[11px] font-semibold">needs manual fix</span>}
158	                  </li>
159	                );
160	              })}
161	            </ul>
162	          )}
163	          {hasBlockers && <p className="mt-3 text-xs text-red-300">Port/path overlaps can’t be auto-applied safely yet — resolve them at the source, or migrate those servers one at a time, then consolidate the rest.</p>}
164	          <button onClick={run} disabled={pending || hasBlockers} className="btn-primary mt-4 disabled:opacity-40">{pending ? "Starting…" : "Consolidate now"}</button>
165	        </div>
166	      )}
167	
168	      {blocked && <p className="mt-4 rounded-lg border border-red-500/25 bg-red-500/[0.06] px-3 py-2 text-sm text-red-200">{blocked}</p>}
169	      {done && <p className="mt-4 rounded-lg border border-emerald-400/25 bg-emerald-400/[0.06] px-3 py-2 text-sm text-emerald-200">Started {done.length} migration{done.length === 1 ? "" : "s"} onto your server — they’ll run one after another. Track progress on the Migrate page.</p>}
170	    </div>
171	  );
172	}
