1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { placeHostingOrder, startHostingCardSetup, checkHostingSubdomain } from "@/lib/actions-hosting";
5	import { finalizeCardSetup } from "@/lib/actions-payment-method";
6	import { termPriceCents, termDiscountPct, ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT, PRODUCT_TERMS, vpsTerm } from "@/lib/billing-terms";
7	import { extraDiskCentsAt, EXTRA_DISK_STEP_GB, EXTRA_DISK_MAX_ADD_GB, EXTRA_DISK_ONE_WAY_NOTE, EXTRA_DISK_DEFAULT_PER_GB_CENTS } from "@/lib/extra-disk";
8	import { TermLadder } from "@/components/customer/TermLadder";
9	import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
10	import { PaymentStep } from "@/components/customer/PaymentStep";
11	import { WizardReassuranceCard } from "@/components/customer/WizardReassuranceCard";
12	import { WizardStickyCart } from "@/components/customer/WizardStickyCart";
13	import { walletSplit } from "@/lib/wallet-split";
14	import { recommendHostingPlan } from "@/lib/hosting/recommend";
15	import { useCurrency } from "@/components/currency/CurrencyContext";
16	import { convertAndFormat, DEFAULT_CURRENCY } from "@/lib/currency";
17	import { trackDeployStep, trackDeployError } from "@/lib/deploy-funnel-client";
18	
19	/* --------------------------------------------------------------- types --- */
20	
21	export type WizardPlan = {
22	  id: string;
23	  name: string;
24	  priceCents: number;
25	  diskGB: number;
26	  maxSites: number;
27	  maxDatabases: number;
28	  bandwidthTB: number;
29	  mailboxes: number;
30	  freeMigration: boolean;
31	  featured: boolean;
32	  tagline: string;
33	};
34	
35	type AppOpt = { slug: string; name: string; needsDb: boolean; blurb?: string; logoPath?: string; logoHex?: string };
36	
37	// USD formatter — this wizard's 2-decimal style ("$5.00"). Used verbatim for the
38	// USD display path (byte-for-byte unchanged) and for the "billed in USD" note.
39	const usd = (c: number) => `$${(c / 100).toFixed(2)}`;
40	
41	/** sessionStorage key for the in-progress order — survives the Stripe card round-trip. */
42	const DRAFT_KEY = "nxeon.hosting.deploy.draft.v1";
43	type Draft = {
44	  step: number;
45	  planId: string;
46	  termMonths: number;
47	  domainMode: "temp" | "own";
48	  domain: string;
49	  /** The chosen free-subdomain label — MUST persist across the card-setup round-trip,
50	   *  else a customer who typed "testing" gets the auto-derived name after adding a card. */
51	  subLabel: string;
52	  extraDiskGB: number;
53	  appSlug: string;
54	};
55	
56	/**
57	 * The one-month first-month-free credit, computed EXACTLY like the server's
58	 * `firstMonthCreditCents` (kept inline so this client file never imports the
59	 * db-backed promo module). A 1-month term is wholly free; a longer term credits a
60	 * single month. The server recomputes the real debit with the same formula, so
61	 * displayed === charged.
62	 */
63	function firstMonthCredit(fullCents: number, months: number): number {
64	  if (months <= 1) return fullCents;
65	  return Math.min(fullCents, Math.round(fullCents / months));
66	}
67	
68	function Stepper({ step, steps }: { step: number; steps: string[] }) {
69	  return (
70	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
71	      {steps.map((s, i) => (
72	        <div key={s} className="flex items-center gap-2">
73	          <span
74	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
75	              i === step
76	                ? "border-brand-400 bg-brand-500/20 text-brand-200"
77	                : i < step
78	                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
79	                  : "border-white/10 text-slate-500"
80	            }`}
81	          >
82	            {i < step ? "✓" : i + 1}
83	          </span>
84	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
85	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
86	        </div>
87	      ))}
88	    </div>
89	  );
90	}
91	
92	/* -------------------------------------------------------------- wizard --- */
93	
94	export function HostingDeployWizard({
95	  plans,
96	  apps,
97	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
98	  firstMonthFree = false,
99	  balanceCents,
100	  hasCard,
101	  cardLabel,
102	  stripeReady,
103	  tempSubdomainBase,
104	  extraDiskPerGbCents = EXTRA_DISK_DEFAULT_PER_GB_CENTS,
105	  email,
106	}: {
107	  plans: WizardPlan[];
108	  apps: AppOpt[];
109	  annualDiscountPct?: number;
110	  firstMonthFree?: boolean;
111	  balanceCents: number;
112	  /** A renewal-capable card is already on file (charged off-session at renewal). */
113	  hasCard: boolean;
114	  cardLabel: string | null;
115	  /** Stripe is configured, so we can capture a card at all. */
116	  stripeReady: boolean;
117	  /** Base zone for the free temporary subdomain, e.g. "nxeon.cloud". */
118	  tempSubdomainBase: string;
119	  /** Price per extra GB / month (cents) — the same add-on rate VPS uses. */
120	  extraDiskPerGbCents?: number;
121	  /** The account's email — PaymentStep's receipt/invoice-email display. */
122	  email: string;
123	}) {
124	  // Steps: Install is only shown when there's an app catalog to pick from.
125	  const hasApps = apps.length > 0;
126	  const steps = ["Plan", "Domain", ...(hasApps ? ["Install"] : []), "Add-ons", "Review"];
127	  const [step, setStep] = useState(0);
128	
129	  // Deploy-funnel: record reaching each wizard step (de-duped per session).
130	  useEffect(() => {
131	    trackDeployStep("hosting", steps[step] ?? String(step), step);
132	    // eslint-disable-next-line react-hooks/exhaustive-deps
133	  }, [step]);
134	
135	  // DISPLAY-ONLY price formatter. USD renders byte-for-byte as before; any other
136	  // selected display currency converts the USD-cents amount for on-screen reference
137	  // only. Everything sent to placeHostingOrder (and the nxTrack value) stays USD.
138	  const { currency, rate } = useCurrency();
139	  const money = (c: number) =>
140	    currency === DEFAULT_CURRENCY ? usd(c) : convertAndFormat(c, currency, rate);
141	
142	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
143	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
144	  const [domainMode, setDomainMode] = useState<"temp" | "own">("temp");
145	  const [domain, setDomain] = useState("");
146	  // Optional customer-chosen free-subdomain label. Empty => the server auto-derives
147	  // `<username>.<base>`. When the customer types one we live-check availability so a
148	  // taken/invalid label is caught before the order (the order re-checks atomically).
149	  const [subLabel, setSubLabel] = useState("");
150	  const [subCheck, setSubCheck] = useState<{ status: "idle" | "checking" | "ok" | "bad"; reason?: string }>({ status: "idle" });
151	  const [extraDiskGB, setExtraDiskGB] = useState(0);
152	  const [appSlug, setAppSlug] = useState("");
153	
154	  // A card the customer just saved via the Stripe round-trip flips this true
155	  // without a page reload, so the Review step stops asking for one.
156	  const [savedCard, setSavedCard] = useState(hasCard);
157	  // "Apply my balance" — mirrors the VPS wizard. Default ON when there's a balance to
158	  // apply; turning it off routes the whole amount due today to a card. The server
159	  // recomputes the identical split (lib/wallet-split.ts), so displayed === charged.
160	  const [useWallet, setUseWallet] = useState(balanceCents > 0);
161	  // Clicking "Change" next to the billing term inside PaymentStep's Order
162	  // Summary used to jump all the way back to step 0 (Plan) — worse than just
163	  // "back one step" when Domain/Install/Add-ons sit in between. Reveals the
164	  // same TermLadder cards inline instead, mirroring DeployWizard's
165	  // showTermPicker pattern.
166	  const [showTermPicker, setShowTermPicker] = useState(false);
167	
168	  const [busy, setBusy] = useState(false);
169	  const [error, setError] = useState("");
170	  const [cardBusy, setCardBusy] = useState(false);
171	  const [cardNote, setCardNote] = useState("");
172	  // `addCard`'s setup-mode session (capture a renewal card, no charge) — this is a
173	  // genuinely different Stripe primitive from a Custom Checkout payment session
174	  // (mode:setup vs mode:payment, still on the OLD embedded_page ui_mode), so it
175	  // keeps using the popup StripeCheckoutModal rather than PaymentStep, which is
176	  // built around confirming a real payable Custom Checkout session.
177	  const [cardSetupCheckout, setCardSetupCheckout] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
178	  // `place()`'s Custom Checkout session (paying the card leg of an order) — feeds
179	  // the embedded PaymentStep, mirroring VPS/Game/Email.
180	  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
181	  const [stripePhase, setStripePhase] = useState<"idle" | "loading" | "error">("idle");
182	  const [restoredAfterSetup, setRestoredAfterSetup] = useState(false);
183	
184	  // ONE idempotency token per wizard mount. A double-click is stopped by `busy`;
185	  // this token is the server-side guard against a network retry creating a second
186	  // account (placeHostingOrder → FulfilledSession UNIQUE). A user-driven retry
187	  // after a failure reuses it safely (the server clears a FAILED marker).
188	  const idemRef = useRef<string>("");
189	  if (!idemRef.current) idemRef.current = makeToken();
190	
191	  const plan = plans.find((p) => p.id === planId) ?? null;
192	  const curLabel = steps[step];
193	  const isLast = step === steps.length - 1;
194	
195	  /* ----- pricing (all DB-fed; the server recomputes the debit identically) -- */
196	  const planTermCents = plan ? termPriceCents(plan.priceCents, termMonths, annualDiscountPct) : 0;
197	  // Extra storage add-on: priced per GB/mo over the term, and NEVER discounted by the
198	  // first-month-free promo (mirrors the server — the credit applies to the plan only).
199	  const extraTermCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGbCents) * termMonths;
200	  const fullTermCents = planTermCents + extraTermCents;
201	  const creditCents = firstMonthFree ? firstMonthCredit(planTermCents, termMonths) : 0;
202	  const dueTodayCents = Math.max(0, planTermCents - creditCents) + extraTermCents;
203	  // What the account renews at — the full term price (plan + storage), promo aside.
204	  const renewalCents = fullTermCents;
205	  const perMonthCents = Math.round(planTermCents / Math.max(1, termMonths));
206	  const termWord = termMonths === ANNUAL_TERM_MONTHS ? "year" : termMonths === 1 ? "month" : `${termMonths} mo`;
207	  // Same rate planTermCents was computed with — shown next to the billing
208	  // term as a "Save X%" badge (DeployWizard's termDiscountPct pattern).
209	  const discountPercent = termDiscountPct(termMonths, annualDiscountPct);
210	  // The sticky cart's price: the FULL per-month total including add-ons
211	  // (extra storage), not just the bare plan rate — a real regression already
212	  // happened once this session (a sticky cart that didn't reflect add-ons),
213	  // so this is computed from fullTermCents (plan + extra disk), never from
214	  // plan.priceCents alone.
215	  const stickyCartMonthlyCents = Math.round(fullTermCents / Math.max(1, termMonths));
216	
217	  // Wallet/card split for the amount due today — identical math to the server
218	  // (placeHostingOrder → walletSplit), so what's shown here === what's charged.
219	  const split = walletSplit({ dueCents: dueTodayCents, balanceCents, useWallet });
220	  const cardCents = split.cardCents;
221	  const walletApplied = split.walletApplied;
222	
223	  // Can we bill the renewal? A saved card OR a wallet already holding a renewal's
224	  // worth OR a card leg on THIS order (the card is saved for renewals via
225	  // setup_future_usage). Mirrors the server: a card-funded order needs no separate
226	  // renewal method.
227	  const renewalMethodOk = savedCard || balanceCents >= renewalCents || cardCents > 0;
228	  // A card leg is due at Review — PaymentStep mounts instead of the plain
229	  // fallback, same condition VPS/Game/Email use.
230	  const showPaymentStep = isLast && cardCents > 0;
231	
232	  // A Custom Checkout session is priced at the moment it's created. If the
233	  // customer flips "Apply my balance" AFTER one exists, its stamped amount is
234	  // stale — drop it so PaymentStep asks for a fresh one. Same guard as the
235	  // other wizards.
236	  const prevCardCentsRef = useRef(cardCents);
237	  useEffect(() => {
238	    if (checkoutSession && prevCardCentsRef.current !== cardCents) {
239	      setCheckoutSession(null);
240	      setStripePhase("idle");
241	    }
242	    prevCardCentsRef.current = cardCents;
243	  }, [cardCents, checkoutSession]);
244	
