/**
 * Per-server extra disk — pure, dependency-free maths + copy.
 *
 * Deliberately has NO server-only imports (no db, no settings) so the exact same
 * module can be imported by client components (DeployWizard, AddStorage) and by
 * the server actions / worker. Whatever the customer SEES is byte-for-byte what
 * gets CHARGED — mirroring lib/wallet-split.ts.
 *
 * This is the server's OWN root disk growing, which is a different product from
 * block-storage volumes (lib/actions-volumes.ts): a volume is portable and can be
 * detached and deleted; this space is fused into the VM's root filesystem.
 *
 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
 * A live filesystem cannot be shrunk without risking data loss, and no serious
 * provider offers it. There is NO shrink path anywhere in the platform, and
 * `Server.extraDiskGB` is never decremented. Every surface that sells extra
 * storage must show EXTRA_DISK_ONE_WAY_NOTE before taking the money.
 */

/** Storage is sold in 10 GB increments — matches the slider/step in both UIs. */
export const EXTRA_DISK_STEP_GB = 10;
/** Smallest purchasable amount. */
export const EXTRA_DISK_MIN_GB = 10;
/** Largest amount purchasable in a SINGLE transaction. */
export const EXTRA_DISK_MAX_ADD_GB = 500;
/** Hard ceiling on a server's effective disk (plan.diskGB + extraDiskGB). */
export const EXTRA_DISK_MAX_TOTAL_GB = 2000;
/**
 * Fallback price per GB per month when the `extra_disk_gb_price_cents` admin
 * setting has never been written. 10 = $0.10/GB/mo, matching block storage.
 * Use `extraDiskMonthlyCents()` (lib/disk-expand.ts) in billing paths, never this.
 */
export const EXTRA_DISK_DEFAULT_PER_GB_CENTS = 10;

/** The one-way warning, shown verbatim on every surface that sells extra disk. */
export const EXTRA_DISK_ONE_WAY_NOTE =
  "Storage can only be added, never removed. Extra disk space is permanent for this server's lifetime and keeps billing every cycle.";

/** A server's EFFECTIVE root disk in GB — plan allowance plus purchased extra. */
export function effectiveDiskGB(planDiskGB: number, extraDiskGB: number | null | undefined): number {
  return Math.max(0, Math.round(planDiskGB)) + Math.max(0, Math.round(extraDiskGB ?? 0));
}

/**
 * Monthly cost (integer cents) of `gb` extra GB at `perGbCents`. Exact integer
 * multiplication — no floating-point money.
 */
export function extraDiskCentsAt(gb: number, perGbCents: number): number {
  const g = Math.max(0, Math.round(gb));
  const p = Math.max(0, Math.round(perGbCents));
  return g * p;
}

/**
 * The one-off charge for `monthlyCents` of extra disk over the months still left
 * on the current paid term. THE single definition, shared by the server
 * (lib/disk-expand.ts diskExpandQuote) and the control that DISPLAYS the figure
 * before the customer agrees to it (components/customer/AddStorage.tsx).
 *
 * It lives in this pure module for exactly the reason `walletSplit` does: the
 * client has to be able to import it, so what is shown is byte-for-byte what is
 * charged. Until 2026-07-27 the server computed
 * `Math.max(0, Math.round(monthlyCents * remainingMonths))` and AddStorage computed
 * the same expression over its OWN private copy of `MS_PER_AVG_MONTH` — the two
 * places agreeing by convention that this codebase has been bitten by repeatedly
 * (the wizard's promo line, the "+30 days" renew button, the resize picker before
 * it was moved onto lib/proration.ts). Pass `remainingMonths(expiresAt, now)` from
 * lib/proration.ts as the second argument; do not re-derive it.
 *
 * Clamped at both ends: an expired term (negative months) prorates to zero rather
 * than crediting, and a negative price can never come out as a negative charge.
 */
export function extraDiskProrateCents(monthlyCents: number, monthsRemaining: number): number {
  const monthly = Math.max(0, monthlyCents);
  const months = Math.max(0, monthsRemaining);
  if (!Number.isFinite(monthly) || !Number.isFinite(months)) return 0;
  return Math.max(0, Math.round(monthly * months));
}

/** Is `gb` a purchasable amount (a positive multiple of the step, within range)? */
export function isValidExtraDiskAddGB(gb: number): boolean {
  return (
    Number.isInteger(gb) &&
    gb >= EXTRA_DISK_MIN_GB &&
    gb <= EXTRA_DISK_MAX_ADD_GB &&
    gb % EXTRA_DISK_STEP_GB === 0
  );
}

/**
 * Coerce arbitrary input to a purchasable amount: rounded DOWN to the step and
 * clamped to [0, EXTRA_DISK_MAX_ADD_GB]. Rounding DOWN (never up) means a
 * malformed value can only ever cost the customer less, never more. Returns 0
 * for "no extra disk", which every caller treats as a no-op.
 */
export function normalizeExtraDiskGB(gb: unknown): number {
  const n = Number(gb);
  if (!Number.isFinite(n) || n <= 0) return 0;
  const stepped = Math.floor(n / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB;
  if (stepped < EXTRA_DISK_MIN_GB) return 0;
  return Math.min(EXTRA_DISK_MAX_ADD_GB, stepped);
}

/** Selectable amounts for the wizard/server-page controls: 10…500 GB by 10. */
export function extraDiskOptions(): number[] {
  const out: number[] = [];
  for (let g = EXTRA_DISK_MIN_GB; g <= EXTRA_DISK_MAX_ADD_GB; g += EXTRA_DISK_STEP_GB) out.push(g);
  return out;
}

/**
 * The largest amount a server can still add without breaching the effective-disk
 * ceiling, rounded DOWN to the step. 0 means "already at the ceiling".
 */
export function maxAddableExtraDiskGB(planDiskGB: number, extraDiskGB: number): number {
  const headroom = EXTRA_DISK_MAX_TOTAL_GB - effectiveDiskGB(planDiskGB, extraDiskGB);
  if (headroom < EXTRA_DISK_MIN_GB) return 0;
  return Math.min(EXTRA_DISK_MAX_ADD_GB, Math.floor(headroom / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB);
}

/** Human label for an extra-disk line item / notification. */
export function extraDiskLabel(gb: number): string {
  return `${Math.max(0, Math.round(gb))} GB extra disk storage`;
}

/**
 * Clamp a raw "extra GB to add" input to a valid, on-step, in-range amount (0
 * allowed) — the SHARED-HOSTING order form's own normalizer. Rounds to the
 * NEAREST step (unlike `normalizeExtraDiskGB` above, which rounds DOWN for the
 * VPS disk-expand slider's "never cost more than shown" guarantee); hosting's
 * extra disk is chosen from a fixed set of stepped options, not typed free-form,
 * so nearest-step is the correct behaviour here and has always been.
 *
 * Lives in this plain module (not lib/actions-hosting.ts, which is a `"use
 * server"` file) so it can be imported by lib/actions-payment-providers.ts
 * (PayPal/Coinbase hosting-order creation) WITHOUT becoming a second
 * network-callable export of a Server Actions module — see
 * test/auth-lockouts.test.ts's "HAZARD" suite, which exists precisely to catch
 * a pure helper being exported from a `"use server"` file for no reason.
 */
export function normalizeExtraDiskAddGB(raw: unknown): number {
  const n = Math.round((Number(raw) || 0) / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB;
  return Math.max(0, Math.min(EXTRA_DISK_MAX_ADD_GB, n));
}
---WALLET---
// Pure, dependency-free wallet/card split math shared by the client wizards
// (DeployWizard, ResizePicker) and the server actions (payAndDeploy,
// resizeServer). Keeping it here — with NO server-only imports — guarantees the
// split the customer SEES is byte-for-byte the split that gets CHARGED.

/**
 * Stripe rejects card charges under ~$0.50. We never send a card amount below
 * this; when the natural remainder would fall under it we leave exactly this
 * much on the card and apply slightly less wallet credit (see walletSplit).
 */
export const STRIPE_MIN_CENTS = 50;

export type WalletSplit = {
  /** Cents taken from the customer's existing wallet balance. */
  walletApplied: number;
  /** Cents charged to the card (0 = fully paid from wallet, no Stripe). */
  cardCents: number;
  /** True when we bumped the card up to STRIPE_MIN_CENTS (reducing wallet). */
  clampedForStripeMin: boolean;
  /**
   * True when the WHOLE amount due is under Stripe's floor, so no card leg exists
   * at all and `walletApplied` is the entire due (see walletSplit). Distinct from
   * `clampedForStripeMin`, which means the opposite thing — that a card leg does
   * exist and was raised to the floor. Surfaces must not conflate them: the deploy
   * wizard's `clampedForStripeMin` line says "we'll charge {cardCents} to your
   * card", which would be a flat lie here, where `cardCents` is 0.
   *
   * In this state `walletApplied` may EXCEED the customer's balance. That is not a
   * claim the balance covers it — it is the amount that must come from the wallet
   * because nothing else can settle it. The caller's guarded `debitWallet` decides
   * whether it succeeds, and a surface showing this flag should tell the customer
   * to top up rather than imply the payment is already funded.
   */
  belowStripeMin: boolean;
};

/**
 * Split a due amount between the wallet and the card, honoring the customer's
 * "apply my balance" toggle and Stripe's minimum-charge floor.
 *
 * - `useWallet` off  → everything on the card.
 * - wallet covers all → cardCents = 0 (caller pays entirely from wallet, no Stripe).
 * - partial cover     → walletApplied = min(balance, due), card = the remainder.
 * - tiny remainder    → if 0 < card < STRIPE_MIN_CENTS, reduce walletApplied so
 *   exactly STRIPE_MIN_CENTS lands on the card (never send Stripe a sub-minimum
 *   charge). Integer-cent exact throughout.
 * - whole due sub-floor → no card leg is possible at all; the wallet takes it all
 *   and `belowStripeMin` is set (see below).
 *
 * POSTCONDITION, relied on by every caller: `cardCents` is either 0 or at least
 * STRIPE_MIN_CENTS. `lib/actions-server.ts` and `lib/actions-disk.ts` hand
 * `cardCents` straight to `createResizeCheckout` / `createDiskExpandCheckout`,
 * which guard only `cardCents <= 0` — a sub-floor positive amount reached
 * `stripe().checkout.sessions.create` and threw out of the server action. That is
 * fixed HERE, in the one function that owns the floor, rather than by bolting a
 * duplicate guard onto each call site.
 */
export function walletSplit(opts: {
  dueCents: number;
  balanceCents: number;
  useWallet: boolean;
}): WalletSplit {
  const dueCents = Math.max(0, Math.round(opts.dueCents));
  const balanceCents = Math.max(0, Math.round(opts.balanceCents));
  if (dueCents <= 0) {
    return { walletApplied: 0, cardCents: 0, clampedForStripeMin: false, belowStripeMin: false };
  }

  // The whole amount due is under Stripe's floor, so there is no card leg to be
  // had: the clamp below works by moving cents from the wallet ONTO the card, and
  // here there are not enough cents in the charge to reach the floor no matter how
  // they are divided. Previously this fell through and returned whatever sub-floor
  // remainder was left (due 30, balance 10 -> cardCents 20), which Stripe rejects.
  //
  // Two behaviours were available and only one is honest. Inflating the card leg to
  // 50c would charge the customer more than they owe. So the card is dropped
  // entirely and the wallet takes the whole amount — the only leg that can settle
  // a 30c charge — REGARDLESS of `useWallet`, because respecting that preference
  // here would mean no payable split exists at all. `belowStripeMin` reports it so
  // callers and surfaces state what happened instead of implying a funded card
  // payment, and when the balance falls short the caller's guarded `debitWallet`
  // fails with the actionable "top up your wallet first" rather than a Stripe API
  // error. Note walletApplied + cardCents === dueCents still holds exactly.
  if (dueCents < STRIPE_MIN_CENTS) {
    return { walletApplied: dueCents, cardCents: 0, clampedForStripeMin: false, belowStripeMin: true };
  }

  let walletApplied = opts.useWallet ? Math.min(balanceCents, dueCents) : 0;
  let cardCents = dueCents - walletApplied;
  let clampedForStripeMin = false;

  // A tiny non-zero card remainder that Stripe would reject. This only happens
  // when the wallet can't cover the whole charge (otherwise cardCents === 0), so
  // the least-surprising fix is to leave STRIPE_MIN_CENTS on the card and apply a
  // touch less wallet. `dueCents >= STRIPE_MIN_CENTS` is guaranteed by the early
  // return above, so walletApplied can never go negative here.
  if (cardCents > 0 && cardCents < STRIPE_MIN_CENTS) {
    walletApplied = dueCents - STRIPE_MIN_CENTS;
    cardCents = STRIPE_MIN_CENTS;
    clampedForStripeMin = true;
  }
  return { walletApplied, cardCents, clampedForStripeMin, belowStripeMin: false };
}
